  "mainEntity" : [ {
    "@type" : "Question",
    "@id" : "https://www.bluehost.com#faq-1",
    "name" : "HOW CAN I GET A FREE DOMAIN NAME?",
    "acceptedAnswer" : {
      "@type" : "Answer",
      "@id" : "https://www.bluehost.com#faq-1-answer",
      "text" : "Bluehost is proud to offer a free domain name with many hosting plans. This can be a great way to save money and simplify the process of setting up a website. Be sure to check the details of the hosting plan to see if a free domain name is included, and view our full policy on free domains."
    }
  }, {
    "@type" : "Question",
    "@id" : "https://www.bluehost.com#faq-2",
    "name" : "WHAT IS THE 30-DAY MONEY-BACK GUARANTEE?",
    "acceptedAnswer" : {
      "@type" : "Answer",
      "@id" : "https://www.bluehost.com#faq-2-answer",
      "text" : "Your satisfaction is our top priority and we're confident you'll be pleased with our services. Still, if you try us and decide your account does not sufficiently meet your needs, you can cancel within 30 days for a refund as follows:&nbsp; If you cancel within 30 days you'll receive a full refund on your hosting service only. The money-back guarantee does not apply to most add-on products, such as domains, given the unique nature of their costs. If you cancel within 30 days and your plan includes a free domain, there will be a fee to retain that domain. Bluehost will deduct a non-refundable domain fee from your refund, at the regular cost of your domain. Bluehost does not offer any refunds for cancellations that occur after 30 days. The money-back guarantee does not apply to Products and Services with a monthly term."
    }
  }, {
    "@type" : "Question",
    "@id" : "https://www.bluehost.com#faq-3",
    "name" : "IS BLUEHOST RECOMMENDED BY WORDPRESS?",
    "acceptedAnswer" : {
      "@type" : "Answer",
      "@id" : "https://www.bluehost.com#faq-3-answer",
      "text" : "Yes, Bluehost is a recommended hosting provider by WordPress. Bluehost offers specialized&nbsp;WordPress Hosting plans&nbsp;that are optimized for the platform, as well as&nbsp;WooCommerce Hosting plans&nbsp;for eCommerce websites. This ensures that websites built on WordPress have optimal performance and security. Users love our user-friendly interface and one-click installation of WordPress, which make it easy for anyone to set up and manage a website. We also invite you to learn more about&nbsp;WonderSuite, an easy WordPress website builder."
    }
  }, {
    "@type" : "Question",
    "@id" : "https://www.bluehost.com#faq-4",
    "name" : "CAN I GET PROFESSIONAL EMAIL HOSTING?",
    "acceptedAnswer" : {
      "@type" : "Answer",
      "@id" : "https://www.bluehost.com#faq-4-answer",
      "text" : "Yes,&nbsp;professional email plans&nbsp;are available through Bluehost.&nbsp;Google Workspace&nbsp;is a popular option for professional email hosting, and can be integrated with many web hosting plans. With professional&nbsp;email hosting, users can have a custom email address with their domain name, giving a more professional look and feel to their communications."
    }
  }, {
    "@type" : "Question",
